// Deathloom fork: campaign guide route (PoE1, acts 1-10).
//
// campaign-route.json is generated by tools/gen-campaign-route.py from Exile
// Leveling's route files (MIT, (c) 2025 HeartofPhos; licence in
// exile-leveling.LICENSE.txt). Regenerate it at each league start. One step per
// zone you enter; the guide moves to the next matching step when Client.txt says
// "You have entered <zone>". Quest passive points sit on the quest's hand-in line.

import ROUTE_JSON from './campaign-route.json'

export type RoutePart = string | {
  k: 'quest' | 'kill' | 'area' | 'waypoint' | 'waypoint_get' | 'trial' | 'logout' | 'dir' | 'generic' |
  'quest_text' | 'arena' | 'crafting' | 'ascend' | 'portal'
  v?: string | number
  // quest: quest id, reward offer id (quest-gems.json), passive / respec points
  id?: string
  offer?: string
  passive?: number
  respec?: number
}
export interface RouteTask { parts: RoutePart[], subs?: RoutePart[][] }
export interface RouteStep {
  zone: string
  areaId: string
  act: number
  town: boolean
  via: 'start' | 'enter' | 'waypoint' | 'logout'
  tasks: RouteTask[]
}

// In route order
export const STEPS = (ROUTE_JSON as unknown as { steps: RouteStep[] }).steps

function stepPassives (st: RouteStep): number {
  let n = 0
  for (const t of st.tasks) for (const p of t.parts) if (typeof p !== 'string' && p.passive) n += p.passive
  return n
}

// Passive points from quests on the route: 24 (23, plus 1 for killing all three bandits)
export const QUEST_PASSIVES = STEPS.reduce((n, st) => n + stepPassives(st), 0)

// Where the guide is (index into STEPS), shared by every window through localStorage
// (v2: the route from 1.0.33; v1 indexes were for the old hand-written route)
export const CAMPAIGN_STEP_KEY = 'deathloom.campaign-step.v2'
export function loadCampaignStep (): number {
  try { return Math.min(STEPS.length - 1, Math.max(0, Number(localStorage.getItem(CAMPAIGN_STEP_KEY)) || 0)) } catch { return 0 }
}

// Quest passive points from the steps before this one (optional quests counted
// as done; /passives in game is exact)
export function questPassivesBefore (index: number): number {
  return STEPS.slice(0, index).reduce((n, st) => n + stepPassives(st), 0)
}

const norm = (z: string) => z.toLowerCase().replace(/^the /, '').trim()

// Act from the area id in Client.txt ('Generating level 13 area "1_3_7"' -> 3;
// "2_6_1" -> 6). null for hideouts, maps and anything else.
export function actFromAreaCode (code: string | undefined): number | null {
  const m = code?.match(/^\d+_(\d+)_/)
  const act = m ? Number(m[1]) : NaN
  return act >= 1 && act <= 10 ? act : null
}

// Forward-only: the next matching step after the current one, so going back
// to a town or an earlier zone never moves the guide backwards. With the act
// known (from the area id) only that act's steps count, so act 1's "The Coast"
// never jumps to act 6's. Without it, only the current and the next act.
// Returns -1 when there's no forward match.
export function findStep (zone: string, current: number, act: number | null = null): number {
  const target = norm(zone)
  const curAct = STEPS[Math.max(0, Math.min(current, STEPS.length - 1))].act
  for (let i = Math.max(0, current + 1); i < STEPS.length; i++) {
    const s = STEPS[i]
    if (act != null ? s.act !== act : s.act > curAct + 1) continue
    if (norm(s.zone) !== target) continue
    // towns come up again and again: a town visit only moves the guide when the
    // route goes there next (a trip to sell doesn't skip zones)
    if (s.town && s.act === curAct && i > current + 2) return -1
    return i
  }
  return -1
}

// Whether the zone is anywhere on the route (for the "not on the route" note)
export function isOnRoute (zone: string): boolean {
  const target = norm(zone)
  return STEPS.some(s => norm(s.zone) === target)
}
